// Enclosure for Eave Weather Station
// Outer: 120 x 80 x 42 mm, Wall: 2 mm
// Features Stevenson-screen ventilation louvers

$fn = 40;
wall = 2.0;
w = 120; d = 80; h = 42;
r = 4;

module rounded_box(x, y, z, rad) {
    hull() {
        translate([-x/2 + rad, -y/2 + rad, 0]) cylinder(r=rad, h=z);
        translate([ x/2 - rad, -y/2 + rad, 0]) cylinder(r=rad, h=z);
        translate([-x/2 + rad,  y/2 - rad, 0]) cylinder(r=rad, h=z);
        translate([ x/2 - rad,  y/2 - rad, 0]) cylinder(r=rad, h=z);
    }
}

module eave_base() {
    difference() {
        rounded_box(w, d, h - 8, r);
        translate([0, 0, wall])
            rounded_box(w - 2*wall, d - 2*wall, h, r - 1);

        // Angled louvers on left and right for weather-shielded airflow
        for (i = [-12:8:12]) {
            translate([w/2 - 1, 14 + i, 12])
                rotate([0, 30, 0])
                    cube([wall + 4, 4, 12]);
        }

        // Rain sensor external wire grommet
        translate([30, -d/2 - 1, 10])
            cube([10, wall + 2, 6]);
    }
}

module eave_lid() {
    translate([0, 0, h + 10]) {
        difference() {
            rounded_box(w, d, 8, r);
            // OLED cutout
            translate([-24, -20, -1])
                cube([25, 15, 12], center=true);
        }
    }
}

eave_base();
eave_lid();

