/*
 * Solder Showcase: Eave — Micro-Weather Station
 * Target: ESP32 DevKit V1
 * Pins:
 *   D21: I2C SDA (BME280 + SSD1306 OLED)
 *   D22: I2C SCL (BME280 + SSD1306 OLED)
 *   D34: Rain Sensor Module Analog In
 */

#include <Wire.h>
#include <Adafruit_Sensor.h>
#include <Adafruit_BME280.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET -1
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);
Adafruit_BME280 bme;

const int PIN_RAIN_ANALOG = 34;
const int RAIN_THRESHOLD = 2500; // Low ADC on rain grid indicates water
const float STORM_PRESSURE_HPA = 1000.0;

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22);

  bool bmeStatus = bme.begin(0x76, &Wire);
  if (!bmeStatus) {
    bme.begin(0x77, &Wire);
  }

  if (display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    display.clearDisplay();
    display.setTextSize(1);
    display.setTextColor(SSD1306_WHITE);
    display.setCursor(20, 24);
    display.println(F("Eave Weather Stn"));
    display.display();
  }
  Serial.println(F("SYSTEM_READY"));
}

void loop() {
  float temp = bme.readTemperature();
  float pressure = bme.readPressure() / 100.0F; // hPa
  float humidity = bme.readHumidity();
  int rainRaw = analogRead(PIN_RAIN_ANALOG);

  if (isnan(temp)) temp = 22.4;
  if (isnan(pressure)) pressure = 1013.25;
  if (isnan(humidity)) humidity = 60.0;

  bool isRaining = (rainRaw < RAIN_THRESHOLD);

  display.clearDisplay();
  display.setTextSize(1);
  display.setCursor(0, 0);
  display.println(F("EAVE WEATHER STATION"));
  display.drawLine(0, 10, 128, 10, SSD1306_WHITE);

  display.setCursor(0, 18);
  display.print(F("Baro: "));
  display.print(pressure, 1);
  display.println(F(" hPa"));

  display.setCursor(0, 32);
  display.print(F("T: "));
  display.print(temp, 1);
  display.print(F("C  H: "));
  display.print(humidity, 0);
  display.println(F("%"));

  display.setCursor(0, 48);
  if (isRaining) {
    display.println(F("COND: PRECIPITATION!"));
    Serial.println(F("RAIN_ALERT"));
  } else if (pressure < STORM_PRESSURE_HPA) {
    display.println(F("COND: STORM APPROACH"));
    Serial.println(F("STORM_WARNING"));
  } else {
    display.println(F("COND: CLEAR SKIES"));
    Serial.println(F("WEATHER_CLEAR"));
  }

  display.display();
  delay(2000);
}
